import{Ct as e,at as t,it as n,ot as r,st as i,t as a,tt as o,yt as s}from"./chunks/framework.CqXnyklt.js";var c=JSON.parse(`{"title":"WarpDrive 5.9","description":"Learn what changed in WarpDrive 5.9 — reactive pagination, the migrate-to-schema codemod, Memory Alpha for AI agents, and rolled-up types — and why to install 5.9.1 rather than 5.9.0.","frontmatter":{"title":"WarpDrive 5.9","date":"2026-09-05T00:00:00.000Z","description":"Learn what changed in WarpDrive 5.9 — reactive pagination, the migrate-to-schema codemod, Memory Alpha for AI agents, and rolled-up types — and why to install 5.9.1 rather than 5.9.0.","outline":{"level":"2,3"}},"headers":[],"relativePath":"blog/v5/warp-drive-5-9.md","filePath":"blog/v5/warp-drive-5-9.md"}`),l={name:`blog/v5/warp-drive-5-9.md`};function u(a,c,l,u,d,f){let p=e(`SinceBadge`);return s(),n(`div`,null,[c[0]||=o(`h1`,{id:`warpdrive-5-9`,tabindex:`-1`},[o(`strong`,null,[o(`em`,null,`Warp`),r(`Drive`)]),r(` 5.9 `),o(`a`,{class:`header-anchor`,href:`#warpdrive-5-9`,"aria-label":`Permalink to “WarpDrive 5.9”`},`​`)],-1),i(p,{version:`5.9.1`}),c[1]||=t(` \xA0 2026-09-05<p><strong><em>Warp</em>Drive</strong> 5.9 is out, and this post is for apps already on 5.x deciding whether and how to upgrade. The headline changes are experimental reactive pagination, a codemod that turns EmberData models into schemas, and a new package of <strong><em>Warp</em>Drive</strong> knowledge for AI coding agents. Before upgrading, read <a href="#changes-that-may-need-attention">Changes That May Need Attention</a>: most apps won&#39;t hit any of them, but the two most likely to are that published types are now rolled up per entry point and that <code>@warp-drive/holodeck</code> now replays its fixtures in CI.</p><h2 id="install-5-9-1-not-5-9-0" tabindex="-1">Install 5.9.1, not 5.9.0 <a class="header-anchor" href="#install-5-9-1-not-5-9-0" aria-label="Permalink to “Install 5.9.1, not 5.9.0”">​</a></h2><p>The 5.9.0 release did not publish completely. Every package went out at 5.9.0 except <code>@warp-drive/experiments</code>, whose publish failed, so there is no <code>@warp-drive/experiments</code> that goes with 5.9.0. Version 5.9.1, released the same day, fixes the release tooling and publishes <code>@warp-drive/experiments</code> at 5.9.1 alongside everything else (<a href="https://github.com/warp-drive-data/warp-drive/pull/11023" target="_blank" rel="noreferrer">#11023</a>). It contains no other changes.</p><p>Install 5.9.1 for every <strong><em>Warp</em>Drive</strong> package you use. If you already installed 5.9.0, move to 5.9.1; there is nothing else to do.</p><p>Starting with 5.9.1, <code>@warp-drive/experiments</code> is versioned with the rest of the 5.x packages instead of on its own <code>0.x</code> line, so its version always matches theirs.</p><h2 id="changes-that-may-need-attention" tabindex="-1">Changes That May Need Attention <a class="header-anchor" href="#changes-that-may-need-attention" aria-label="Permalink to “Changes That May Need Attention”">​</a></h2><p>Each of these can surface after upgrading, and each says what to do about it.</p><h3 id="types-are-rolled-up-per-entry-point" tabindex="-1">Types are rolled up per entry point <a class="header-anchor" href="#types-are-rolled-up-per-entry-point" aria-label="Permalink to “Types are rolled up per entry point”">​</a></h3><p>The <code>@warp-drive/*</code> packages now build with rolldown (via tsdown) instead of Vite (<a href="https://github.com/warp-drive-data/warp-drive/pull/10643" target="_blank" rel="noreferrer">#10643</a>). Imports and module format are unchanged, but declarations now live in <code>dist/</code> next to the JavaScript and are rolled up into one file per public entry point (<code>@warp-drive/core</code> goes from 130 <code>.d.ts</code> files to 60). If you imported a type from an internal module path that isn&#39;t a package entry point, it no longer resolves: import it from its public entry point instead. As a bonus, editor import suggestions now only offer public paths, and packages ship sourcemaps.</p><h3 id="holodeck-replays-in-ci" tabindex="-1">Holodeck replays in CI <a class="header-anchor" href="#holodeck-replays-in-ci" aria-label="Permalink to “Holodeck replays in CI”">​</a></h3><p><code>@warp-drive/holodeck</code> was meant to record locally and replay from its <code>.mock-cache</code> fixtures when <code>CI</code> is set, but it always recorded, so a test whose fixture was never committed still passed in CI. It now replays as intended (<a href="https://github.com/warp-drive-data/warp-drive/pull/10698" target="_blank" rel="noreferrer">#10698</a>). If tests start failing in CI after upgrading, run them locally and commit the fixtures they write; set <code>IS_RECORDING</code> to record even when <code>CI</code> is set. Replay also now finds mocks whose URL includes a query string, such as <code>GET(this, &#39;users?name=Chris&#39;, ...)</code>.</p><h3 id="witharraydefaults-field-types" tabindex="-1"><code>withArrayDefaults</code> field types <a class="header-anchor" href="#witharraydefaults-field-types" aria-label="Permalink to “withArrayDefaults field types”">​</a></h3><p><code>withArrayDefaults</code> from <code>@warp-drive/legacy/model-fragments</code> takes an optional second argument for the item type: <code>withArrayDefaults(&#39;titles&#39;, &#39;string&#39;)</code> produces a field of type <code>array:string</code>, matching <code>array(&#39;string&#39;)</code> in ember-data-model-fragments (<a href="https://github.com/warp-drive-data/warp-drive/pull/10421" target="_blank" rel="noreferrer">#10421</a>). Without it the field type is now <code>array</code>; it used to be derived from the singularized field name (<code>array:title</code>). If you relied on that, pass the item type explicitly.</p><h3 id="no-more-ember-barrel-import" tabindex="-1">No more <code>ember</code> barrel import <a class="header-anchor" href="#no-more-ember-barrel-import" aria-label="Permalink to “No more ember barrel import”">​</a></h3><p><code>ember-data</code> and <code>@warp-drive/legacy</code> no longer import the <code>ember</code> barrel module, removing a blocker for Ember 7 (<a href="https://github.com/warp-drive-data/warp-drive/pull/10513" target="_blank" rel="noreferrer">#10513</a>). As a result, <code>ember-data</code> no longer registers itself in <code>Ember.libraries</code>, and <code>cacheFor</code> on records using the <code>EmberObjectExtension</code> or <code>EmberObjectArrayExtension</code> from <code>@warp-drive/legacy/compat/extensions</code> now throws, since Ember removed it with no replacement.</p><h3 id="generators-no-longer-write-classic-or-pods-output" tabindex="-1">Generators no longer write classic or pods output <a class="header-anchor" href="#generators-no-longer-write-classic-or-pods-output" aria-label="Permalink to “Generators no longer write classic or pods output”">​</a></h3><p>The <code>ember generate</code> blueprints for models, adapters, serializers and transforms (and their unit tests) no longer generate classic <code>Model.extend()</code> syntax or pods layouts; they always write native classes at the default paths (<a href="https://github.com/warp-drive-data/warp-drive/pull/10866" target="_blank" rel="noreferrer">#10866</a>). See <a href="#warp-drive-generate"><code>warp-drive generate</code></a> below.</p><h2 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to “New Features”">​</a></h2><h3 id="reactive-pagination-experimental" tabindex="-1">Reactive pagination (experimental) <a class="header-anchor" href="#reactive-pagination-experimental" aria-label="Permalink to “Reactive pagination (experimental)”">​</a></h3><p><code>getPaginationState(request)</code> from <code>@warp-drive/experiments/pagination</code> returns a reactive pagination state for a request, built on the pagination links in <strong><em>Warp</em>Drive</strong> response documents (<a href="https://github.com/warp-drive-data/warp-drive/pull/10014" target="_blank" rel="noreferrer">#10014</a>). It comes in two flavors: paged (<code>activePage</code>, <code>totalPages</code>, <code>loadPage(url)</code>) and infinite (<code>data</code>, <code>hasNext</code>, <code>loadNext()</code>, <code>loadPrev()</code>). Loaded pages are cached per collection, so every component paginating the same collection shares them while keeping its own navigation state.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { getPaginationState } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/experiments/pagination&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> request</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> store.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ url: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/users&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, method: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;GET&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> pages</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getPaginationState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(request);</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> request;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pages.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">loadNext</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p>Ember apps also get <code>&lt;Paginate /&gt;</code> and <code>&lt;EachLink /&gt;</code> from <code>@warp-drive/ember/experiments</code>. <code>&lt;Paginate /&gt;</code> mirrors <code>&lt;Request /&gt;</code>&#39;s blocks and picks a flavor with <code>@mode=&quot;paged&quot;</code> (the default) or <code>@mode=&quot;infinite&quot;</code>. This feature lives in <code>@warp-drive/experiments</code>, which is one more reason to install <a href="#install-5-9-1-not-5-9-0">5.9.1</a>.</p><h3 id="migrate-models-to-schemas-with-a-codemod" tabindex="-1">Migrate models to schemas with a codemod <a class="header-anchor" href="#migrate-models-to-schemas-with-a-codemod" aria-label="Permalink to “Migrate models to schemas with a codemod”">​</a></h3><p><code>@ember-data/codemods</code> adds <code>migrate-to-schema</code>, which turns EmberData models and mixins into <strong><em>Warp</em>Drive</strong> schemas: a <code>LegacyResourceSchema</code> built with <code>withDefaults</code>, a TypeScript type, an extension for computed properties and methods, and traits for mixins and intermediate base classes (<a href="https://github.com/warp-drive-data/warp-drive/pull/10466" target="_blank" rel="noreferrer">#10466</a>). It handles JavaScript and TypeScript models, leaves the original files in place, writes to <code>app/data/</code> by default, and logs each file it skips and why. A JSON config covers custom transform types, base classes, monorepo sources, and where your app imports <strong><em>Warp</em>Drive</strong> APIs from (<code>warpDriveImports</code>).</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @ember-data/codemods</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate-to-schema</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project-name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span></code></pre></div><p>The CLI now ships as a portable Node bundle that runs on macOS, Linux and Windows via <code>npx</code>, <code>pnpm dlx</code> or <code>bunx</code>. See <a href="/pr-preview/pr-11402/upgrading/v5/codemods">Using Codemods</a>.</p><h3 id="memory-alpha-warpdrive-knowledge-for-ai-agents" tabindex="-1">Memory Alpha: <strong><em>Warp</em>Drive</strong> knowledge for AI agents <a class="header-anchor" href="#memory-alpha-warpdrive-knowledge-for-ai-agents" aria-label="Permalink to “Memory Alpha: WarpDrive knowledge for AI agents”">​</a></h3><p><code>@warp-drive/memory-alpha</code> is a new package of <strong><em>Warp</em>Drive</strong> knowledge for AI coding agents such as Claude Code, Codex, Copilot, Cursor and Gemini (<a href="https://github.com/warp-drive-data/warp-drive/pull/10665" target="_blank" rel="noreferrer">#10665</a>). It has no code: it ships a <code>skills/</code> directory of small, task-focused markdown files, starting with defining a resource schema and fetching and caching data through the <code>Store</code>, plus a <code>skills/index.md</code> routing table that sends an agent straight to the one file matching its task.</p><p>To use it, install the package, copy the instruction file for your agent from the package README (<code>CLAUDE.md</code>, <code>AGENTS.md</code>, <code>GEMINI.md</code>, Copilot instructions or a Cursor rule), and point it at <code>node_modules/@warp-drive/memory-alpha/skills/index.md</code>, or serve the <code>skills/</code> directory from an MCP server. The same skills are readable by humans in the <a href="/pr-preview/pr-11402/skills/">Skills</a> section of the docs site.</p><h3 id="stateful-request-handlers" tabindex="-1">Stateful request handlers <a class="header-anchor" href="#stateful-request-handlers" aria-label="Permalink to “Stateful request handlers”">​</a></h3><p>The <code>handlers</code> option of <code>useRecommendedStore</code> (<code>@warp-drive/core</code>) and <code>useLegacyStore</code> (<code>@warp-drive/legacy</code>) also accepts a function that receives the store and returns the handler list (<a href="https://github.com/warp-drive-data/warp-drive/pull/10551" target="_blank" rel="noreferrer">#10551</a>). It runs once per store, the first time <code>store.requestManager</code> is read, so handlers can depend on the store or its owner, such as an Ember service.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> default</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useRecommendedStore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  cache: JSONAPICache,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  handlers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">store</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> authHandler</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AuthHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    setOwner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(authHandler, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getOwner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(store)</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [authHandler];</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><h3 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h3><ul><li><strong>LinksMode without related links.</strong> <code>linksMode</code> relationships no longer require a <code>links.related</code> link when the payload is &quot;fully linked&quot;: a <code>belongsTo</code> with <code>data: null</code> or a related resource in <code>included</code>, or a <code>hasMany</code> with <code>data: []</code> or every member in <code>included</code>. A relationship with no <code>data</code> key still needs a related link. In PolarisMode, a sync <code>linksMode</code><code>belongsTo</code> can now be set on an editable (checked-out) record, and resources built with <code>withDefaults</code> get a <code>$key</code> field that returns the record&#39;s <code>ResourceKey</code>. See <a href="/pr-preview/pr-11402/guides/the-manual/misc/links-mode">LinksMode</a> (<a href="https://github.com/warp-drive-data/warp-drive/pull/10524" target="_blank" rel="noreferrer">#10524</a>).</li><li><strong>Abstract polymorphic types need no schema.</strong> For resources defined with schemas, when a concrete type&#39;s relationship declares <code>as: &#39;abstract-pet&#39;</code>, registering that type&#39;s schema also builds the schema for <code>abstract-pet</code>; before, resolving the relationship threw. A real schema you register for the abstract type is merged with the fields its implementers add, and development builds now catch conflicting field shapes and point misconfiguration errors at the side that needs fixing. See <a href="/pr-preview/pr-11402/guides/the-manual/relational-data/features/polymorphism">Polymorphism</a> (<a href="https://github.com/warp-drive-data/warp-drive/pull/10547" target="_blank" rel="noreferrer">#10547</a>).</li></ul><h3 id="easier-migration-from-model" tabindex="-1">Easier migration from <code>Model</code> <a class="header-anchor" href="#easier-migration-from-model" aria-label="Permalink to “Easier migration from Model”">​</a></h3><p><code>@attr</code>, <code>@belongsTo</code> and <code>@hasMany</code> in <code>@warp-drive/legacy/model</code> accept a <code>sourceKey</code> option for when the API&#39;s field name differs from the property name: <code>@attr(&#39;string&#39;, { sourceKey: &#39;first-name&#39; }) firstName</code> reads and writes <code>first-name</code> in the cache (<a href="https://github.com/warp-drive-data/warp-drive/pull/10549" target="_blank" rel="noreferrer">#10549</a>). The same release fixes several rough edges for apps that mix <code>Model</code>s with schema-only resources while they migrate: <code>JSONSerializer</code>&#39;s <code>shouldSerializeHasMany</code> and the <code>EmbeddedRecordsMixin</code> work for resources with no <code>Model</code> class, <code>store.modelFor()</code> no longer asserts on stores created with <code>useLegacyStore({ linksMode: true })</code>, and looking up fields for a type with no registered model throws <code>No model was found for &#39;&lt;type&gt;&#39;</code> instead of recursing forever.</p><h3 id="warp-drive-generate" tabindex="-1"><code>warp-drive generate</code> <a class="header-anchor" href="#warp-drive-generate" aria-label="Permalink to “warp-drive generate”">​</a></h3><p>The <code>warp-drive</code> CLI adds <code>warp-drive generate &lt;type&gt; &lt;name&gt;</code> (aliases <code>g</code> and <code>gen</code>), which writes a model, adapter, serializer or transform, or a unit test for one, without going through ember-cli (<a href="https://github.com/warp-drive-data/warp-drive/pull/10866" target="_blank" rel="noreferrer">#10866</a>). The <code>ember generate</code> blueprints keep working and now produce the same output as the CLI.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> warp-drive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> taco</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filling:belongs-to:protein</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toppings:has-many:topping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name:string</span></span></code></pre></div><h3 id="payload-validation-in-the-cache-log" tabindex="-1">Payload validation in the cache log <a class="header-anchor" href="#payload-validation-in-the-cache-log" aria-label="Permalink to “Payload validation in the cache log”">​</a></h3><p>When <a href="/pr-preview/pr-11402/guides/the-manual/debugging/"><code>LOG_CACHE</code></a> is on, the payload report <code>JSONAPICache</code> logs in development also checks the compound-document rules of the {json:api} spec (<a href="https://github.com/warp-drive-data/warp-drive/pull/10433" target="_blank" rel="noreferrer">#10433</a>). It flags a resource that appears more than once in the same payload, a relationship whose <code>data</code> points at a resource the payload doesn&#39;t include, and an <code>included</code> resource that no relationship reaches from the primary <code>data</code>. Duplicates are a common slip in hand-written mocks, and the report names every place the resource appears.</p><h3 id="linting" tabindex="-1">Linting <a class="header-anchor" href="#linting" aria-label="Permalink to “Linting”">​</a></h3><p><code>eslint-plugin-warp-drive</code> gains its first template rule, <code>template-always-use-request-content</code>, which flags a <code>&lt;Request&gt;</code> whose result is never used, which usually means the data is being read some other way and bypasses the boundary <code>&lt;Request&gt;</code> sets up (<a href="https://github.com/warp-drive-data/warp-drive/pull/10613" target="_blank" rel="noreferrer">#10613</a>). A new <code>eslint-plugin-warp-drive/recommended-templates</code> config wires up <code>ember-eslint-parser</code> for <code>.gjs</code>/<code>.gts</code> files and enables it. The <code>no-legacy-imports</code> autofix now preserves type-only imports, and reports legacy imports it can&#39;t map safely instead of skipping them. See <a href="/pr-preview/pr-11402/guides/linting/">Linting</a>.</p><h3 id="fetch-improvements" tabindex="-1">Fetch improvements <a class="header-anchor" href="#fetch-improvements" aria-label="Permalink to “Fetch improvements”">​</a></h3><p>The <code>Fetch</code> handler in <code>@warp-drive/core</code> now supports <code>HEAD</code> requests, resolving them with <code>null</code> content, and requests can pass the native <code>priority</code> fetch hint (<code>&#39;high&#39;</code>, <code>&#39;low&#39;</code> or <code>&#39;auto&#39;</code>) without failing development-mode validation (<a href="https://github.com/warp-drive-data/warp-drive/pull/10463" target="_blank" rel="noreferrer">#10463</a>).</p><p>In development builds, the fetch handler guesses whether Mirage (or another Pretender-based mock) is serving requests, and the guess can be wrong either way. Call <code>globalThis.setWarpDriveIsMaybeMirage(true)</code> or <code>(false)</code> to override it, including outside tests for Mirage in <code>ember serve</code>. A wrong guess also no longer throws when the response&#39;s headers are immutable (<a href="https://github.com/warp-drive-data/warp-drive/pull/10543" target="_blank" rel="noreferrer">#10543</a>).</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to “Performance”">​</a></h2><p>When a push changes several fields on a record, <code>JSONAPICache</code> now hands the store&#39;s notification manager all of them in one call instead of one call per field, which saves work when you push large payloads. Subscribers see no difference: they are still called once per changed field (<a href="https://github.com/warp-drive-data/warp-drive/pull/10614" target="_blank" rel="noreferrer">#10614</a>, <a href="https://github.com/warp-drive-data/warp-drive/pull/10560" target="_blank" rel="noreferrer">#10560</a>). To support this, <code>store.notifications.notify()</code> accepts an array or <code>Set</code> of keys, as does a cache&#39;s <code>notifyChange()</code> for <code>&#39;attributes&#39;</code>. <code>@warp-drive/core</code> also exports a new <code>NotificationChannel</code> type (<code>&#39;local&#39; | &#39;remote&#39;</code>) that custom <code>Cache</code> implementations can pass to <code>notify()</code>, <code>subscribe()</code> and <code>notifyChange()</code> to report local edits separately from remote state; leave it out to keep the old behavior.</p><h2 id="notable-fixes" tabindex="-1">Notable Fixes <a class="header-anchor" href="#notable-fixes" aria-label="Permalink to “Notable Fixes”">​</a></h2><ul><li><strong><em>Warp</em>Drive</strong> no longer crashes in environments without full browser globals, like React Native. Without <code>window.addEventListener</code> and <code>document</code>, the online/visibility listeners that drive <code>&lt;Request /&gt;</code> auto-refresh are skipped, and abort errors fall back to a plain <code>Error</code> with the same <code>name</code> (<a href="https://github.com/warp-drive-data/warp-drive/pull/10612" target="_blank" rel="noreferrer">#10612</a>).</li><li>A sync <code>linksMode</code> hasMany on an immutable record no longer goes stale after repeated remote updates (<a href="https://github.com/warp-drive-data/warp-drive/pull/10560" target="_blank" rel="noreferrer">#10560</a>).</li><li>Reading a <code>hasMany</code> after a record on its inverse side was unloaded no longer throws &quot;Expected localState to be present&quot;; <code>splice(start)</code> with no delete count now removes everything from <code>start</code> onward, like <code>Array.prototype.splice</code>; and development builds now throw when two relationships on a type declare the same explicit <code>inverse</code>, instead of silently corrupting it (<a href="https://github.com/warp-drive-data/warp-drive/pull/10533" target="_blank" rel="noreferrer">#10533</a>).</li><li><code>JSONAPISerializer</code> skips resources of unknown types in a payload&#39;s primary <code>data</code> array instead of crashing, and <code>RESTAdapter</code> returns an <code>InvalidError</code> instead of throwing when a 422 response has a <code>null</code> body (<a href="https://github.com/warp-drive-data/warp-drive/pull/10649" target="_blank" rel="noreferrer">#10649</a>).</li></ul><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to “Documentation”">​</a></h2><p>The Manual is reorganized into topic sections, and several pages that were placeholders in 5.8 are now written (<a href="https://github.com/warp-drive-data/warp-drive/pull/10519" target="_blank" rel="noreferrer">#10519</a>):</p><ul><li><a href="/pr-preview/pr-11402/guides/the-manual/reactivity/">Reactivity</a> explains how <strong><em>Warp</em>Drive</strong> uses signals as &quot;gates&quot; next to the cache rather than as storage, with new pages on <a href="/pr-preview/pr-11402/guides/the-manual/reactivity/control-flow">Reactive Control Flow</a> and <a href="/pr-preview/pr-11402/guides/the-manual/reactivity/derivation">Async as Reactive State</a>.</li><li><a href="/pr-preview/pr-11402/guides/the-manual/debugging/">Debugging</a> covers turning on instrumented logging at runtime or build time and what each log flag shows.</li><li>The schema guides gain full pages on <a href="/pr-preview/pr-11402/guides/the-manual/schemas/derivations">Derivations</a>, <a href="/pr-preview/pr-11402/guides/the-manual/schemas/transformations">Transformations</a>, <a href="/pr-preview/pr-11402/guides/the-manual/schemas/traits">Traits</a> and <a href="/pr-preview/pr-11402/guides/the-manual/schemas/complex-fields">Complex Fields</a>.</li><li>The TypeScript guides&#39; examples now import from <code>@warp-drive/core</code> and <code>@warp-drive/legacy</code> instead of the pre-5.x <code>@ember-data/*</code> packages.</li></ul><p>The <a href="/pr-preview/pr-11402/api/">API reference</a> also fills in a large number of previously undocumented public types and members across <code>@warp-drive/core</code>, <code>@warp-drive/legacy</code>, <code>@warp-drive/utilities</code>, <code>@warp-drive/ember</code> and <code>@warp-drive/react</code>, with union members and related types now linked to each other (<a href="https://github.com/warp-drive-data/warp-drive/pull/10569" target="_blank" rel="noreferrer">#10569</a>).</p><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to “Upgrading”">​</a></h2><p>Install <a href="#install-5-9-1-not-5-9-0">5.9.1</a>, then check the <a href="#changes-that-may-need-attention">Changes That May Need Attention</a> above. If you&#39;re moving from <code>Model</code>s to schemas, start with <a href="/pr-preview/pr-11402/upgrading/v5/codemods">Using Codemods</a>.</p><h2 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to “Thanks”">​</a></h2><p>Thank you to everyone who contributed to 5.9: Chris Thoburn (<a href="https://github.com/runspired" target="_blank" rel="noreferrer">@runspired</a>), Vaibhav Srivastava (<a href="https://github.com/vaibhav8a" target="_blank" rel="noreferrer">@vaibhav8a</a>), Sergey Astapov (<a href="https://github.com/SergeAstapov" target="_blank" rel="noreferrer">@SergeAstapov</a>), Bartlomiej Dudzik (<a href="https://github.com/BobrImperator" target="_blank" rel="noreferrer">@BobrImperator</a>), Sam Van Campenhout (<a href="https://github.com/Windvis" target="_blank" rel="noreferrer">@Windvis</a>), Krystan HuffMenne (<a href="https://github.com/gitKrystan" target="_blank" rel="noreferrer">@gitKrystan</a>), Mehul Kiran Chaudhari (<a href="https://github.com/MehulKChaudhari" target="_blank" rel="noreferrer">@MehulKChaudhari</a>), Chris Manson (<a href="https://github.com/mansona" target="_blank" rel="noreferrer">@mansona</a>), Marine Dunstetter (<a href="https://github.com/BlueCutOfficial" target="_blank" rel="noreferrer">@BlueCutOfficial</a>), Markus Sanin (<a href="https://github.com/mkszepp" target="_blank" rel="noreferrer">@mkszepp</a>), Kirill Shaplyko (<a href="https://github.com/Baltazore" target="_blank" rel="noreferrer">@Baltazore</a>), Liam (<a href="https://github.com/evoactivity" target="_blank" rel="noreferrer">@evoactivity</a>), David Baker (<a href="https://github.com/acorncom" target="_blank" rel="noreferrer">@acorncom</a>), Michal Bryxí (<a href="https://github.com/MichalBryxi" target="_blank" rel="noreferrer">@MichalBryxi</a>), Alex Raputa (<a href="https://github.com/alexraputa" target="_blank" rel="noreferrer">@alexraputa</a>), Leo Euclides (<a href="https://github.com/leoeuclids" target="_blank" rel="noreferrer">@leoeuclids</a>), Thomas Gossmann (<a href="https://github.com/gossi" target="_blank" rel="noreferrer">@gossi</a>), PJ Carly (<a href="https://github.com/pjcarly" target="_blank" rel="noreferrer">@pjcarly</a>), <a href="https://github.com/NullVoxPopuli-ai-agent" target="_blank" rel="noreferrer">@NullVoxPopuli-ai-agent</a>, Rich Glazerman (<a href="https://github.com/richgt" target="_blank" rel="noreferrer">@richgt</a>) and <a href="https://github.com/BoussonKarel" target="_blank" rel="noreferrer">@BoussonKarel</a>.</p><p>See the full release notes for <a href="https://github.com/warp-drive-data/warp-drive/blob/v5.9.0/CHANGELOG.md" target="_blank" rel="noreferrer">5.9.0</a> and <a href="https://github.com/warp-drive-data/warp-drive/blob/v5.9.1/CHANGELOG.md" target="_blank" rel="noreferrer">5.9.1</a>.</p>`,60)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};